#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Create temporary env files\nold=$(mktemp)\nnew=$(mktemp)\n\ncat > "$old" <<'EOF'\n# Sample old env\nDB_HOST=localhost\nDB_PORT=5432\nDEBUG=true\nEOF\n\ncat > "$new" <<'EOF'\n# Sample new env\nDB_HOST=db.example.com\nDB_PORT=5432\nVERBOSE=false\nEOF\n\n# Run the diff script\noutput=$(../src/diff_env.sh "$old" "$new")\n\n# Expected output (order independent)\nexpected=$(cat <<'EEOF'\nChanged: DB_HOST (\"localhost\" -> \"db.example.com\")\nRemoved: DEBUG\nAdded: VERBOSE\nEEOF\n)\n\n# Sort both for comparison\nsorted_output=$(echo "$output" | sort)\nsorted_expected=$(echo "$expected" | sort)\n\nif [[ "$sorted_output" != "$sorted_expected" ]]; then\n  echo "Test failed"\n  echo "Expected:"\n  echo "$sorted_expected"\n  echo "Got:"\n  echo "$sorted_output"\n  exit 1\nfi\n\necho "All tests passed"\n
